obs=json.loads((root/'src/data/local-observations.json').read_text(encoding='utf-8'));photo=next(o for o in obs if o['scientificName']=='Basilinna leucotis');bird=dict(audio='audio/birds/local.wav',image=photo['photo'],commonName=photo['commonName'],scientificName=photo['scientificName'],source='https://www.inaturalist.org/observations/'+str(x['id']))
(root/'src/data/local-bird.json').write_text(json.dumps(bird,ensure_ascii=False,indent=2),encoding='utf-8');mp=root/'public/bibliography/media.json';m=json.loads(mp.read_text(encoding='utf-8'));m.append(dict(id='local-song',type='audio',source=bird['source'],author=s.get('attribution',x['user']['login']),license='CC BY 4.0',attribution=str(s.get('attribution',''))+' · Grabación original sin edición. Fecha: '+x['observed_on'],localPath=bird['audio'],alt='Vocalización de Basilinna leucotis; registro local de iNaturalist.'));mp.write_text(json.dumps(m,ensure_ascii=False,indent=2),encoding='utf-8');print(x['observed_on'],x['location'],s,len(r.content))
